-- FILE: SQL_2026-08-14_fundamentallyai_positive_definition.sql
-- fundamentallyai.com content_direction -> positive-definition form.
--
-- WHY: owner, 2026-08-12, reading the live site: "please relook at the copy as it
-- looks a bit AI generated with the negative framing. We have solved this elsewhere
-- so there should be nothing to invent here."
-- THE RULE (owner, 2026-08-11, mortgagecalculator_couk_adoption, commit 82d510bb5):
--   "Say what a thing IS, not what it is not."
-- THE CAUSE: the spec TAUGHT the X-not-Y construction by example, and examples
-- outweigh rules for a writer. 3 of 4 characteristic example phrases used it.
--
-- 'formatted' was regenerated by the REAL datahelpers.FormatContentDirection via a
-- scratch module with a replace onto the repo -- NOT hand-replicated. The writer
-- reads only {{.site_specs.specs.content_direction.formatted}}, so an edit to
-- 'data' alone would have been a dead edit.
--
-- Supersedes rather than edits in place, so the history stays readable.
-- REVERT: UPDATE site_specs SET is_current=true, superseded_at=NULL WHERE id='%OLD%';
--         DELETE FROM site_specs WHERE id='%NEW%';  (ids printed below)

BEGIN;

-- preconditions ------------------------------------------------------------
DO $chk$
DECLARE n int; cur text;
BEGIN
  SELECT count(*) INTO n FROM site_specs
   WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd'
     AND aspect='content_direction' AND is_current;
  IF n <> 1 THEN
    RAISE EXCEPTION 'expected exactly 1 current content_direction, found %', n;
  END IF;

  SELECT data->>'formatted' INTO cur FROM site_specs
   WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd'
     AND aspect='content_direction' AND is_current;
  -- the defect must still be present, or another session got here first
  IF cur NOT LIKE '%Evidence-first, not assertion-first%' THEN
    RAISE EXCEPTION 'defect ABSENT from current spec -- another session may have fixed it; STOP and re-read';
  END IF;
END $chk$;

-- supersede ----------------------------------------------------------------
UPDATE site_specs
   SET is_current=false, superseded_at=now()
 WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd'
   AND aspect='content_direction' AND is_current;

INSERT INTO site_specs (site_id, aspect, data, source, source_agent, created_by, notes, is_current)
VALUES (
  '199733a8-ac9c-4c30-b2ce-65ecdac6f3bd',
  'content_direction',
  $spec${"compliance_rules":[],"content_depth":{"assumed_knowledge":"Reader is technically literate and commercially experienced. They know what LLMs, fine-tuning, embeddings, and multi-agent systems are — no need to define these from scratch. They are also familiar with consultancy positioning tropes and will spot them immediately. Do not condescend; do not over-explain.","explanation_pattern":"State the capability plainly. Give one specific, concrete example of it working. Acknowledge any current limitation plainly, stating it as what is true rather than what it is not — 'this estimate assumes a fixed rate' carries everything 'this is not a forecast' carries, and tells the reader more. Invite the reader to verify or ask. Make the point first, then support it.","thoroughness":"Thorough on the things that differentiate; brief on the things that don't. The multi-agent review council, the self-correction story, and the rapid delivery capability deserve real explanation with specifics. Standard consultancy services (workshops, strategy, etc.) are not offered — do not pad with them."},"cta_style":{"approach":"Understated, concrete, and non-pushy. A CTA should describe what happens when you click it, not promise a transformation. Suited to a reader who is evaluating, not impulse-buying.","verb_choices":"Talk to us. See the record. Read the case. Review the capability. Ask a question. Start a conversation. — Never: 'Get started free', 'Claim your slot', 'Don't miss out', 'Book now'."},"example_phrases":{"characteristic":["Every substantial change on this platform is reviewed by a council of agents before it ships, and the decision record shows each reviewer's objection and how it was answered.","We caught our own platform generating invented details on leopardessconsulting.co.uk. Our verification system flagged it; we corrected it. That is what happened, and the correction is on the record.","This is a capability we can build for you. The hard technical groundwork exists and works. We have not yet delivered it to a paying client; if that matters to your evaluation, it should.","Rapid delivery is a demonstrated property of this platform: a fully designed, working site in well under a day, and the output is there to look at."],"would_never_say":["Our AI-powered solutions transform your business end-to-end.","Join hundreds of satisfied clients who trust FundamentallyAI.","Limited availability — book your free strategy call today!","We leverage cutting-edge machine learning to unlock your organisation's potential.","Our proprietary algorithms deliver next-generation results."]},"formatted":"Cta style:\nApproach: Understated, concrete, and non-pushy. A CTA should describe what happens when you click it, not promise a transformation. Suited to a reader who is evaluating, not impulse-buying.\nVerb choices: Talk to us. See the record. Read the case. Review the capability. Ask a question. Start a conversation. — Never: 'Get started free', 'Claim your slot', 'Don't miss out', 'Book now'.\n\nTerminology:\nApproach: Use the field's correct technical vocabulary without apology — the audience knows it. On first use of a term specific to this platform's own architecture (e.g. 'multi-agent review council'), give a one-line plain-English gloss immediately after, then use the term without re-explaining.\nKey terms:\n- multi-agent review council\n- decision record\n- fine-tuning\n- embeddings\n- orchestration\n- production integration\n- digital asset recovery\n- verification\n- LLM\n- agentic pipeline\n\nContent depth:\nThoroughness: Thorough on the things that differentiate; brief on the things that don't. The multi-agent review council, the self-correction story, and the rapid delivery capability deserve real explanation with specifics. Standard consultancy services (workshops, strategy, etc.) are not offered — do not pad with them.\nAssumed knowledge: Reader is technically literate and commercially experienced. They know what LLMs, fine-tuning, embeddings, and multi-agent systems are — no need to define these from scratch. They are also familiar with consultancy positioning tropes and will spot them immediately. Do not condescend; do not over-explain.\nExplanation pattern: State the capability plainly. Give one specific, concrete example of it working. Acknowledge any current limitation plainly, stating it as what is true rather than what it is not — 'this estimate assumes a fixed rate' carries everything 'this is not a forecast' carries, and tells the reader more. Invite the reader to verify or ask. Make the point first, then support it.\n\nHeading style:\nFormat: Declarative noun phrases or tight active clauses. Headings carry the substance of the section — a reader skimming headings alone should understand the site's offer. Avoid gerunds ('Delivering AI…') in favour of noun constructions ('AI delivery that…') or plain active verbs ('We ship with a decision record').\nHierarchy: H1 for the single most important claim per page — one per page, never more. H2 for major section titles. H3 for sub-points within a section. Do not skip levels. Do not use headings purely for visual spacing — every heading should be load-bearing copy.\n\nWriting rules:\n- Never invent a person, client, case study, or statistic. Every claim needs a real source or must be explicitly flagged as a capability not yet delivered to a client.\n- Name real artefacts where they exist — leopardessconsulting.co.uk as the self-correction case study, the decision record as the review council's output — rather than gesturing at 'a process'.\n- When describing a capability that has not been delivered for a paying client, say so plainly. Frame it as accurate positioning.\n- Do not use AI-industry buzzwords unanchored from evidence: 'autonomous', 'intelligent', 'next-generation', 'cutting-edge' — only if directly supported by a described mechanism.\n- All numbers and statistics presented on the site must come from real, verifiable figures rendered as code-generated charts — not estimated, rounded, or illustrative unless explicitly labelled as such.\n- Distinguish consistently between 'platform capability' (something the platform demonstrably does) and 'client delivery' (something delivered to a paying client). Do not blur this line.\n- The private in-house search / embeddings capability must always be framed as 'something we can build for you — the hard technical groundwork exists and works' — never as a live, guaranteed product.\n- Vary sentence openings — do not start consecutive sentences with 'We'. Rotate between third-person description, evidence statements, and direct address.\n- Write headings as statements or noun phrases. Questions feel like they belong to a different register. 'A review council that ships decisions with its objections attached' rather than 'How do we ensure quality?'\n- CTAs should be calm invitations, not urgency-driven commands. 'Talk to us' or 'See the decision record' rather than 'Get started now' or 'Book a free call today'.\n\nThings to avoid:\n- Any invented testimonial, client name, statistic, or case study — fabrication is a platform-level disqualifying error\n- Hype vocabulary unanchored from mechanism: 'revolutionary', 'game-changing', 'transformative', 'state-of-the-art' without direct evidence\n- Urgency and scarcity language: 'limited availability', 'act now', 'don't miss out', 'only a few spots left'\n- Generic consultancy filler: 'we partner with you', 'your success is our success', 'end-to-end solutions', 'thought leadership'\n- Passive voice when an active construction is available — passive obscures who did what\n- Charts or statistics presented as images rather than code-generated from real data\n- Photography of real or AI-generated individuals — line illustration only for human figures\n- Implying that a capability not yet delivered to a client has been — the line between platform-demonstrated and client-delivered must always be explicit\n- Over-qualifying to the point of sounding unsure — evidence-grounded claims should be stated with confidence, then supported\n\nPersuasion approach:\nMethod: Evidence-first: describe what was done, what the result was, and what can be verified — then let the reader draw the conclusion. Avoid superlatives. If something is genuinely unusual (e.g. publicly catching and correcting our own AI errors), describe it factually and let the unusualness speak.\nTrust building: Name real artefacts: the decision record, the sibling site (leopardessconsulting.co.uk), the restored subscriber feed. Specificity is the trust signal. Saying what has not yet been done for clients builds more trust than fabricated case studies. Treat 'we haven't done this for a client yet' as a selling point — it means our track record is clean.\nSocial proof style: No invented testimonials, ever. If real client references exist, quote them accurately with attribution. If they do not yet exist, present platform capabilities as demonstrated-on-own-properties rather than client-verified. Frame it plainly: 'We've done this for ourselves — here is the evidence. We haven't yet done it for a paying client; if you want to be first, the capability is real.'\n\nSentence style:\nRhythm: Varies deliberately. A short, declarative sentence after a more complex one resets the reader's pace. Section introductions can be one punchy sentence. Evidence and explanation follow at medium pace. Never monotonous.\nAverage length: Medium. Shorter in hero and navigation copy; medium in body; slightly longer in technical explanations — but never sprawling. No sentence should need to be re-read to parse.\nStructure patterns: Active voice throughout. Lead with the most important information. Qualify claims immediately after making them — 'We fine-tune on real usage data, evaluated against alternatives on the same benchmark.' Avoid subordinate clauses that bury the headline.\n\nExample phrases:\nCharacteristic:\n- Every substantial change on this platform is reviewed by a council of agents before it ships, and the decision record shows each reviewer's objection and how it was answered.\n- We caught our own platform generating invented details on leopardessconsulting.co.uk. Our verification system flagged it; we corrected it. That is what happened, and the correction is on the record.\n- This is a capability we can build for you. The hard technical groundwork exists and works. We have not yet delivered it to a paying client; if that matters to your evaluation, it should.\n- Rapid delivery is a demonstrated property of this platform: a fully designed, working site in well under a day, and the output is there to look at.\nWould never say:\n- Our AI-powered solutions transform your business end-to-end.\n- Join hundreds of satisfied clients who trust FundamentallyAI.\n- Limited availability — book your free strategy call today!\n- We leverage cutting-edge machine learning to unlock your organisation's potential.\n- Our proprietary algorithms deliver next-generation results.\n\nParagraph style:\nStructure: Point first, then support. If a paragraph makes a claim, the claim is the first sentence. Evidence, qualification, or elaboration follows. No paragraph should end on a tangent — the final sentence should land, not trail.\nTypical length: Two to four sentences for body copy. One sentence is acceptable for emphasis or transition. Five or more sentences signals that the paragraph should be split or a bullet list used instead.\n\nThings to emulate:\n- McKinsey.com's section structure: a substantive claim followed by evidence, repeated — no decorative filler between\n- The directness of well-written technical audit reports: 'We found X. It caused Y. We fixed it by doing Z.' Applied to capability descriptions.\n- Bain's use of data visualisation: real figures, clearly sourced, never decorative — every chart answers a specific question the reader might have\n- The self-awareness of the best engineering blogs — willing to describe a mistake, explain what went wrong, and show the correction\n- Numbered or lettered differentiators stated plainly: 'There are five things this platform does that most AI vendors cannot verify. Here they are.'\n- Structural variety across pages — not every page the same template — so the site rewards exploration rather than feeling like a brochure stamped from one mould\n- Accessibility-first interactive components: carousel pausable by keyboard and mouse, first card complete standalone, graceful degradation — these are visible quality signals to a technical audience\n- Positive definition (owner ruling, 2026-08-11): say what a thing IS, not what it is not. A negative definition makes the reader do subtraction and reads colder, because it withholds. Worked example: 'treat the result as a starting conversation' carries everything 'not a verdict' carries, and reads warmer.\n\nVoice:\nFormality: Formal but not stiff. Full sentences, no slang, minimal contractions in headers but allowed in flowing copy. The tone of a well-written briefing note, not a sales deck.\nEmotional tone: Calm and grounded. Acknowledges the reader's scepticism as rational rather than trying to overcome it with enthusiasm. Intellectually respectful — treats the reader as a peer who can evaluate evidence.\nAuthority level: Authority established through specificity and verifiability — naming real sites, real outcomes, real decision records. Never asserts expertise in the abstract. Credentials shown through demonstrated work, not claimed titles.\nPerson: Second person (you/your) when addressing the reader's situation or concerns. First plural (we/our) for the firm. Avoid 'I' — this is a firm, not a personal blog.\nRegister: Measured, precise, and understated. The register of a senior partner at a strategy consultancy — someone who has seen enough overpromised AI projects to be sceptical of their own field. Confident without self-promotion; direct without bluntness.","heading_style":{"format":"Declarative noun phrases or tight active clauses. Headings carry the substance of the section — a reader skimming headings alone should understand the site's offer. Avoid gerunds ('Delivering AI…') in favour of noun constructions ('AI delivery that…') or plain active verbs ('We ship with a decision record').","hierarchy":"H1 for the single most important claim per page — one per page, never more. H2 for major section titles. H3 for sub-points within a section. Do not skip levels. Do not use headings purely for visual spacing — every heading should be load-bearing copy."},"paragraph_style":{"structure":"Point first, then support. If a paragraph makes a claim, the claim is the first sentence. Evidence, qualification, or elaboration follows. No paragraph should end on a tangent — the final sentence should land, not trail.","typical_length":"Two to four sentences for body copy. One sentence is acceptable for emphasis or transition. Five or more sentences signals that the paragraph should be split or a bullet list used instead."},"persuasion_approach":{"method":"Evidence-first: describe what was done, what the result was, and what can be verified — then let the reader draw the conclusion. Avoid superlatives. If something is genuinely unusual (e.g. publicly catching and correcting our own AI errors), describe it factually and let the unusualness speak.","social_proof_style":"No invented testimonials, ever. If real client references exist, quote them accurately with attribution. If they do not yet exist, present platform capabilities as demonstrated-on-own-properties rather than client-verified. Frame it plainly: 'We've done this for ourselves — here is the evidence. We haven't yet done it for a paying client; if you want to be first, the capability is real.'","trust_building":"Name real artefacts: the decision record, the sibling site (leopardessconsulting.co.uk), the restored subscriber feed. Specificity is the trust signal. Saying what has not yet been done for clients builds more trust than fabricated case studies. Treat 'we haven't done this for a client yet' as a selling point — it means our track record is clean."},"sentence_style":{"average_length":"Medium. Shorter in hero and navigation copy; medium in body; slightly longer in technical explanations — but never sprawling. No sentence should need to be re-read to parse.","rhythm":"Varies deliberately. A short, declarative sentence after a more complex one resets the reader's pace. Section introductions can be one punchy sentence. Evidence and explanation follow at medium pace. Never monotonous.","structure_patterns":"Active voice throughout. Lead with the most important information. Qualify claims immediately after making them — 'We fine-tune on real usage data, evaluated against alternatives on the same benchmark.' Avoid subordinate clauses that bury the headline."},"terminology":{"approach":"Use the field's correct technical vocabulary without apology — the audience knows it. On first use of a term specific to this platform's own architecture (e.g. 'multi-agent review council'), give a one-line plain-English gloss immediately after, then use the term without re-explaining.","key_terms":["multi-agent review council","decision record","fine-tuning","embeddings","orchestration","production integration","digital asset recovery","verification","LLM","agentic pipeline"]},"things_to_avoid":["Any invented testimonial, client name, statistic, or case study — fabrication is a platform-level disqualifying error","Hype vocabulary unanchored from mechanism: 'revolutionary', 'game-changing', 'transformative', 'state-of-the-art' without direct evidence","Urgency and scarcity language: 'limited availability', 'act now', 'don't miss out', 'only a few spots left'","Generic consultancy filler: 'we partner with you', 'your success is our success', 'end-to-end solutions', 'thought leadership'","Passive voice when an active construction is available — passive obscures who did what","Charts or statistics presented as images rather than code-generated from real data","Photography of real or AI-generated individuals — line illustration only for human figures","Implying that a capability not yet delivered to a client has been — the line between platform-demonstrated and client-delivered must always be explicit","Over-qualifying to the point of sounding unsure — evidence-grounded claims should be stated with confidence, then supported"],"things_to_emulate":["McKinsey.com's section structure: a substantive claim followed by evidence, repeated — no decorative filler between","The directness of well-written technical audit reports: 'We found X. It caused Y. We fixed it by doing Z.' Applied to capability descriptions.","Bain's use of data visualisation: real figures, clearly sourced, never decorative — every chart answers a specific question the reader might have","The self-awareness of the best engineering blogs — willing to describe a mistake, explain what went wrong, and show the correction","Numbered or lettered differentiators stated plainly: 'There are five things this platform does that most AI vendors cannot verify. Here they are.'","Structural variety across pages — not every page the same template — so the site rewards exploration rather than feeling like a brochure stamped from one mould","Accessibility-first interactive components: carousel pausable by keyboard and mouse, first card complete standalone, graceful degradation — these are visible quality signals to a technical audience","Positive definition (owner ruling, 2026-08-11): say what a thing IS, not what it is not. A negative definition makes the reader do subtraction and reads colder, because it withholds. Worked example: 'treat the result as a starting conversation' carries everything 'not a verdict' carries, and reads warmer."],"voice":{"authority_level":"Authority established through specificity and verifiability — naming real sites, real outcomes, real decision records. Never asserts expertise in the abstract. Credentials shown through demonstrated work, not claimed titles.","emotional_tone":"Calm and grounded. Acknowledges the reader's scepticism as rational rather than trying to overcome it with enthusiasm. Intellectually respectful — treats the reader as a peer who can evaluate evidence.","formality":"Formal but not stiff. Full sentences, no slang, minimal contractions in headers but allowed in flowing copy. The tone of a well-written briefing note, not a sales deck.","person":"Second person (you/your) when addressing the reader's situation or concerns. First plural (we/our) for the firm. Avoid 'I' — this is a firm, not a personal blog.","register":"Measured, precise, and understated. The register of a senior partner at a strategy consultancy — someone who has seen enough overpromised AI projects to be sceptical of their own field. Confident without self-promotion; direct without bluntness."},"writing_rules":["Never invent a person, client, case study, or statistic. Every claim needs a real source or must be explicitly flagged as a capability not yet delivered to a client.","Name real artefacts where they exist — leopardessconsulting.co.uk as the self-correction case study, the decision record as the review council's output — rather than gesturing at 'a process'.","When describing a capability that has not been delivered for a paying client, say so plainly. Frame it as accurate positioning.","Do not use AI-industry buzzwords unanchored from evidence: 'autonomous', 'intelligent', 'next-generation', 'cutting-edge' — only if directly supported by a described mechanism.","All numbers and statistics presented on the site must come from real, verifiable figures rendered as code-generated charts — not estimated, rounded, or illustrative unless explicitly labelled as such.","Distinguish consistently between 'platform capability' (something the platform demonstrably does) and 'client delivery' (something delivered to a paying client). Do not blur this line.","The private in-house search / embeddings capability must always be framed as 'something we can build for you — the hard technical groundwork exists and works' — never as a live, guaranteed product.","Vary sentence openings — do not start consecutive sentences with 'We'. Rotate between third-person description, evidence statements, and direct address.","Write headings as statements or noun phrases. Questions feel like they belong to a different register. 'A review council that ships decisions with its objections attached' rather than 'How do we ensure quality?'","CTAs should be calm invitations, not urgency-driven commands. 'Talk to us' or 'See the decision record' rather than 'Get started now' or 'Book a free call today'."]}$spec$::jsonb,
  'owner 2026-08-12: copy reads AI-generated (negative framing); positive-definition rule owner 2026-08-11',
  'brochure_contrast_front_thread',
  'brochure_contrast_front_thread',
  'Rewrites only the strings the WRITER COPIES (few-shot + worked examples) into positive form: example_phrases.characteristic[0,1,3], persuasion_approach.method, writing_rules[8] good-heading example, content_depth.explanation_pattern (gains a positive worked example). Adds the positive-definition rule to things_to_emulate. DELIBERATELY UNTOUCHED: instruction-to-writer strings that use not/rather-than to tell the writer what to avoid (voice.person, voice.formality, writing_rules[1], writing_rules[9], things_to_avoid[5], persuasion_approach.social_proof_style) -- those are rules, not copy. The honesty requirement SURVIVES: characteristic[2] keeps "We have not yet delivered it to a paying client" and explanation_pattern keeps "Acknowledge any current limitation plainly".',
  true
);

-- postconditions -----------------------------------------------------------
DO $post$
DECLARE f text; n int;
BEGIN
  SELECT count(*) INTO n FROM site_specs
   WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd'
     AND aspect='content_direction' AND is_current;
  IF n <> 1 THEN RAISE EXCEPTION 'post: % current rows, expected 1', n; END IF;

  SELECT data->>'formatted' INTO f FROM site_specs
   WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd'
     AND aspect='content_direction' AND is_current;

  IF f IS NULL OR length(f) < 5000 THEN
    RAISE EXCEPTION 'post: formatted missing or truncated (len %)', coalesce(length(f),-1);
  END IF;

  -- the five taught constructions must be GONE from the field the writer reads
  IF f LIKE '%not a log entry%'            THEN RAISE EXCEPTION 'post: characteristic[0] survived'; END IF;
  IF f LIKE '%not a marketing story%'      THEN RAISE EXCEPTION 'post: characteristic[1] survived'; END IF;
  IF f LIKE '%platform, not a promise%'    THEN RAISE EXCEPTION 'post: characteristic[3] survived'; END IF;
  IF f LIKE '%not assertion-first%'        THEN RAISE EXCEPTION 'post: persuasion.method survived'; END IF;
  IF f LIKE '%decisions, not opinions%'    THEN RAISE EXCEPTION 'post: writing_rules[8] survived'; END IF;

  -- and the honesty must have SURVIVED (the control: this edit must not be a deletion)
  IF f NOT LIKE '%not yet delivered it to a paying client%' THEN
    RAISE EXCEPTION 'post: honesty clause LOST -- this edit deleted a caveat it must keep'; END IF;
  IF f NOT LIKE '%Acknowledge any current limitation plainly%' THEN
    RAISE EXCEPTION 'post: limitation clause LOST'; END IF;
  IF f NOT LIKE '%say what a thing IS%' THEN
    RAISE EXCEPTION 'post: positive-definition rule not present'; END IF;
END $post$;

SELECT id, is_current, superseded_at, created_by, length(data->>'formatted') AS fmt_len
  FROM site_specs
 WHERE site_id='199733a8-ac9c-4c30-b2ce-65ecdac6f3bd' AND aspect='content_direction'
 ORDER BY created_at DESC LIMIT 3;

COMMIT;
